parameters.jsCode:
const input = $input.first().json;

return [{
  json: {
    expert: 'project_context',
    success: false,
    reply: '',
    citations: [],
    warnings: [
      'Project Context Expert is not configured with a valid vector store ID.'
    ],
    proposals: [],
    recommended_actions: [],
    session_id: input.session_id
  }
}];

const response = $input.first().json ?? {};

const originalInput =
  $('Project Retrieval Config').first().json ?? {};

if (response.error) {
  const errorMessage =
    response.error.message ??
    response.message ??
    'Project documentation retrieval failed.';

  return [{
    json: {
      expert: 'project_context',
      success: false,
      reply: '',
      citations: [],
      warnings: [String(errorMessage)],
      proposals: [],
      recommended_actions: [],
      session_id: originalInput.session_id
    }
  }];
}

let reply = '';
const citations = [];

const outputs = Array.isArray(response.output)
  ? response.output
  : [];

for (const outputItem of outputs) {
  if (outputItem?.type !== 'message') {
    continue;
  }

  const contentItems = Array.isArray(outputItem.content)
    ? outputItem.content
    : [];

  for (const content of contentItems) {
    if (content?.type !== 'output_text') {
      continue;
    }

    if (content.text) {
      reply += `${content.text}\n`;
    }

    const annotations = Array.isArray(content.annotations)
      ? content.annotations
      : [];

    for (const annotation of annotations) {
      if (annotation?.type !== 'file_citation') {
        continue;
      }

      citations.push({
        type: 'file',
        file_id: annotation.file_id ?? null,
        filename: annotation.filename ?? null,
        expert: 'project_context'
      });
    }
  }
}

const uniqueCitations = [
  ...new Map(
    citations.map(citation => [
      `${citation.file_id}:${citation.filename}`,
      citation
    ])
  ).values()
];

reply = reply.trim();

return [{
  json: {
    expert: 'project_context',
    success: Boolean(reply),
    reply,
    citations: uniqueCitations,
    warnings: reply
      ? []
      : ['Project documentation retrieval returned no answer.'],
    proposals: [],
    recommended_actions: [],
    session_id: originalInput.session_id
  }
}];

parameters.jsonBody:
={{
  {
    model: $json.model,
    input:
      "You are the Project Context Expert for the Smartwatch Haptic system.\n\n" +
      "Answer only from the uploaded project documentation. " +
      "Explain uncertainty clearly. Do not invent workflow names, database tables, " +
      "files, citations, or system behavior. You are read-only and must never claim " +
      "that you changed the database or an n8n workflow.\n\n" +
      "Question:\n" +
      $json.message,

    tools: [
      {
        type: "file_search",
        vector_store_ids: [$json.vector_store_id],
        max_num_results: 5
      }
    ],

    tool_choice: {
      type: "file_search"
    },

    include: [
      "file_search_call.results"
    ]
  }
}}
